    Path("assets/datasets/movielens/recommendation_lab.json").read_text(
        encoding="utf-8"
    )
)

case = lab["samples"][0]
seen = {i for i, r in case["history"]}
catalog = {i for i, t, g in lab["movies"]}
for method, items in case["top"].items():
    ids = [i for i, s in items]
    assert len(ids) == 10 and len(set(ids)) == 10
    assert set(ids) <= catalog and not seen.intersection(ids)
print("all seen", len(seen), "eligible candidates", len(catalog - seen))

