from pathlib import Path
import json

lab = json.loads(
    Path("assets/datasets/movielens/recommendation_lab.json").read_text(
        encoding="utf-8"
    )
)
u = lab["samples"][0]["user"]
v = lab["samples"][0]["neighbours"][0][0]
a = {i for uid, i, r, t in lab["train"] if uid == u and r >= 4}
b = {i for uid, i, r, t in lab["train"] if uid == v and r >= 4}
result = len(a & b) / (len(a) * len(b)) ** 0.5
print(result)

