from pathlib import Path
import json

lab = json.loads(
    Path("assets/datasets/movielens/recommendation_lab.json").read_text(
        encoding="utf-8"
    )
)
values = []
for row in lab["rows"]:
    if row["train_count"] and row["eligible"]:
        values.append(
            len(set(row["rankings"]["user_cf"]) & set(row["eligible"]))
            / len(row["eligible"])
        )
result = sum(values) / len(values)
print(result)

from pathlib import Path
import json

lab = json.loads(
    Path("assets/datasets/movielens/recommendation_lab.json").read_text(
        encoding="utf-8"
    )
)
fit_users = {u for u, i, r, t in lab["train"]}
future_positive_users = {u for u, i, r, t in lab["future"] if r >= 4}
result = len(future_positive_users - fit_users)
print(result)
